import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CFuv5BrO.js";const m=JSON.parse('{"title":"Day06 · Workflows, skills, and the evaluation console","description":"","frontmatter":{"title":"Day06 · Workflows, skills, and the evaluation console","outline":false},"headers":[],"relativePath":"en/log/day-06.md","filePath":"en/log/day-06.md","lastUpdated":1794305977000}'),n={name:"en/log/day-06.md"};function i(r,e,s,l,c,u){return a(),o("div",null,[...e[0]||(e[0]=[d('<p>2026-11-09 moved Hearth&#39;s product entrances, task workflow, and evaluation infrastructure forward at the same time. 89 commits touched 445 files (+24,538/−1,793): the morning completed task follow-ups, the Git workspace, approval previews, the PWA shell, and browser E2E; the day then made memory provenance, consolidation, forgetting, and skill lifecycle auditable, and ended by building the first complete evaluation control plane for cases, console, run orchestration, and human review.</p><p>The theme was not more concepts. It was making existing capabilities usable every day, reviewable through evidence, and independently evaluable. A page may look complete, but follow-ups must respect scheduling, skills must keep permissions and generations, and the evaluation console must trace every run to its real trajectory.</p><h2 id="interaction-and-task-workflow" tabindex="-1">Interaction and task workflow <a class="header-anchor" href="#interaction-and-task-workflow" aria-label="Permalink to &quot;Interaction and task workflow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Task follow-ups</td><td>A running task can queue &quot;continue after this turn&quot; or abort the current turn and rerun with added information; both keep the task, artifacts, and existing evidence</td></tr><tr><td>Git workspace</td><td>Task detail shows workspace and branch diffs, files, commits, previews, PR state, and CI checks instead of treating terminal output as the final result</td></tr><tr><td>Approval and tools</td><td>The native runtime pauses before sensitive tools; file writes, commands, network access, and screenshots wait when approval is required, continue when approved, and skip with a reason when rejected</td></tr><tr><td>PWA and navigation</td><td>Adds an installable manifest, icons, offline shell, mobile bottom navigation, and command palette; task and approval pages remain usable on narrow screens</td></tr><tr><td>Screenshots and home</td><td>An isolated instance generates README and documentation screenshots; the home page leads with product surfaces, positioning, and current state instead of abstract architecture alone</td></tr></tbody></table><h2 id="memory-skills-and-execution-input" tabindex="-1">Memory, skills, and execution input <a class="header-anchor" href="#memory-skills-and-execution-input" aria-label="Permalink to &quot;Memory, skills, and execution input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Provenance and trust</td><td>Memory records source, confidence, taint, sensitivity, validity, and purpose; recall filters by scope and trust</td></tr><tr><td>Consolidation</td><td>Consolidation handles only explainable duplication and conflict while preserving source chain, versions, and report; model summaries do not become new facts</td></tr><tr><td>Forget propagation</td><td>Forgetting covers projections, versions, events, recall audit, device sync, derived memory, and consolidation, and leaves tombstones so old content cannot return</td></tr><tr><td>Skill lifecycle</td><td>Skill packages support export, import, inspection, pinning, archive, and restore; adopted methods can become scoped skills</td></tr><tr><td>Automation</td><td>Finished tasks best-effort generate method candidates, while stale skills can be curated with rollback; auto-learning remains gated by a switch and evidence rules</td></tr></tbody></table><h2 id="goals-completion-and-the-evaluation-control-plane" tabindex="-1">Goals, completion, and the evaluation control plane <a class="header-anchor" href="#goals-completion-and-the-evaluation-control-plane" aria-label="Permalink to &quot;Goals, completion, and the evaluation control plane&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Goal contract</td><td>Exposes goal creation, query, acceptance criteria, budget, deadline, stop conditions, and review policy</td></tr><tr><td>Completion judgement</td><td>Adds evidence-driven completion: each criterion, evidence item, missing item, and forbidden action is checked; goal tasks cannot close without a verdict</td></tr><tr><td>Case catalog</td><td>Adds a case catalog loader, legacy manifest compatibility, and samples for email, calendar, documents, research, code, web, desktop, and cross-app work</td></tr><tr><td>Evaluation console</td><td>Adds dashboard, case catalog, experiment launch, run trajectory, human review, experiment comparison, and system status pages</td></tr><tr><td>Evaluation service</td><td>Persists evaluation lifecycle and orchestrates runs, human review, control-plane APIs, and artifact boundaries as a code loop</td></tr><tr><td>Documentation</td><td>Documents the standalone evaluation workflow and refreshes README and screenshots; case and product template structures still share some code temporarily</td></tr></tbody></table><h2 id="commits" tabindex="-1">Commits <a class="header-anchor" href="#commits" aria-label="Permalink to &quot;Commits&quot;">​</a></h2><h3 id="_2026-11-09-89-commits-selected" tabindex="-1">2026-11-09 (89 commits, selected) <a class="header-anchor" href="#_2026-11-09-89-commits-selected" aria-label="Permalink to &quot;2026-11-09 (89 commits, selected)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Commit</th><th>Author</th><th>Changes</th></tr></thead><tbody><tr><td><code>9ec69ce</code></td><td>JasonBuildAI</td><td>Rewrote README and the documentation home with product screenshots, current state, and reading entrances; 15 files (+1,083/−342).</td></tr><tr><td><code>7843359</code></td><td>JasonBuildAI</td><td>Added task follow-ups, abort-and-rerun, tool approvals, Git workspace, PWA shell, command palette, and narrow-screen interaction; 47 files (+4,380/−100).</td></tr><tr><td><code>149e7c9</code></td><td>JasonBuildAI</td><td>Added repeatable browser E2E in an isolated data directory covering chat, tasks, settings, key masking, and recovery; 6 files (+533/−6).</td></tr><tr><td><code>d01f61f</code></td><td>JasonBuildAI</td><td>Persisted memory provenance, confidence, taint, sensitivity, and validity; 4 files (+229/−22).</td></tr><tr><td><code>3ff7889</code></td><td>JasonBuildAI</td><td>Added auditable memory consolidation with sources, versions, grouping reasons, and a report; 7 files (+565/−22).</td></tr><tr><td><code>be07437</code></td><td>JasonBuildAI</td><td>Propagated forgetting to projections, versions, events, sync, and derived memory, with tombstones; 6 files (+396/−52).</td></tr><tr><td><code>0d06a3a</code></td><td>JasonBuildAI</td><td>Persisted skill lifecycle and exposed export, import, inspection, pinning, archive, and restore; 6 files (+632/−9).</td></tr><tr><td><code>4e46792</code></td><td>JasonBuildAI</td><td>Exported adopted methods as permission-scoped skill packages; 3 files (+490).</td></tr><tr><td><code>85d9886</code></td><td>JasonBuildAI</td><td>Added a case catalog loader with legacy manifest compatibility across task families; 33 files (+740).</td></tr><tr><td><code>ce57f05</code></td><td>JasonBuildAI</td><td>Made the evaluation service orchestrate runs and human review with lifecycle, failed samples, and review actions; 3 files (+935/−1).</td></tr><tr><td><code>2c415d9</code></td><td>JasonBuildAI</td><td>Added evidence-driven completion judgement over criteria, evidence, missing items, and forbidden actions; 2 files (+413).</td></tr><tr><td><code>c828e5f</code></td><td>JasonBuildAI</td><td>Exposed the goal contract API for criteria, budget, and review policy; 1 file (+134/−3).</td></tr><tr><td><code>aa93b56</code></td><td>JasonBuildAI</td><td>Required a completion verdict before closing a goal task instead of treating executor exit as completion; 3 files (+104).</td></tr></tbody></table><h2 id="boundaries-and-next-step" tabindex="-1">Boundaries and next step <a class="header-anchor" href="#boundaries-and-next-step" aria-label="Permalink to &quot;Boundaries and next step&quot;">​</a></h2><ul><li>The PWA shell, mobile navigation, and offline shell are entrances, not phone pairing, system push, or remote takeover; those remain unaccepted.</li><li>Task follow-ups act on turn boundaries, not inside a live token stream. The Git workspace depends on a real repository and credentials and has no multi-repository stress acceptance.</li><li>Memory consolidation, forget propagation, and skill lifecycle have automated tests but no real long-term personal data, wrong-memory drill, or production method comparison.</li><li>Completion judgement is connected to goals and scheduling, but subjective quality, real business impact, and cross-device handoff still require human acceptance.</li><li>The evaluation console, case catalog, and service form a code loop, but no real experiment has run; the next day moves them to a standalone repository with only a bridge left in the main repository.</li><li>Real accounts, devices, phone entry, and long-running acceptance for Phases 2–6 are unchanged.</li></ul>',13)])])}const p=t(n,[["render",i]]);export{m as __pageData,p as default};
